using System.Text.Json; using Microsoft.EntityFrameworkCore; using Nakama.Api.BuildingBlocks.Persistence; using Nakama.Api.BuildingBlocks.Time; using Nakama.Api.Modules.Notifications.Domain;
namespace Nakama.Api.Modules.Notifications;
public interface INotificationWriter{Task WriteAsync(IEnumerable<Guid> recipients,Guid? actor,NotificationType type,Guid? projectId,Guid? taskId,object? metadata,CancellationToken ct);}
public sealed class NotificationWriter(NakamaDbContext db,IClock clock):INotificationWriter{public async Task WriteAsync(IEnumerable<Guid> recipients,Guid? actor,NotificationType type,Guid? projectId,Guid? taskId,object? metadata,CancellationToken ct){var ids=recipients.Where(x=>x!=Guid.Empty&&x!=actor).Distinct().ToArray();if(ids.Length==0)return;var disabled=await db.NotificationPreferences.Where(x=>ids.Contains(x.UserId)&&x.Type==type&&!x.IsEnabled).Select(x=>x.UserId).ToListAsync(ct);var json=metadata is null?null:JsonSerializer.Serialize(metadata);db.Notifications.AddRange(ids.Except(disabled).Select(x=>Notification.Create(x,actor,type,projectId,taskId,json,clock)));}}
